/* Demonstrates the use of time(2) to retrieve the current timestamp and convert it to a readable format. */
#include <stdio.h>
#include <time.h>
#include <stdlib.h>
#include <errno.h>
#include <string.h>

int main() {
    time_t current_time;
    time_t return_value;

    // Retrieve the time, storing the value in current_time and relying on the return value
    return_value = time(&current_time);

    if (return_value == ((time_t) -1)) {
        fprintf(stderr, "Error calling time(): %s\n", strerror(errno));
        if (errno == EOVERFLOW) {
            fprintf(stderr, "Warning: time_t overflow detected.\n");
        }
        return EXIT_FAILURE;
    }

    // Print the raw timestamp value
    printf("Time since Epoch (seconds): %ld\n", (long)current_time);

    // Convert the time_t value into a human-readable string (e.g., 'Wed Jun 30 21:49:08 2021\n')
    // ctime(3) uses a static buffer, so it is not thread-safe, but useful for demonstration.
    char *time_str = ctime(&current_time);
    printf("Current Time: %s", time_str);

    return EXIT_SUCCESS;
}
